const srmProjectPage=p=>`<p class="back-link"><a href="projects.html">← All projects</a></p><header class="srm-hero"><div class="srm-hero-copy"><p class="eyebrow">SupplyCopia · Healthcare supply chain</p><h1>AI-powered supplier relationship management</h1><p class="srm-role">Lead AI Product Manager <span aria-hidden="true">·</span> September 2025 – Present</p><p class="srm-deck">Replaced weeks of manual vendor review and disconnected compliance checks with a self-serve SRM: six onboarding steps, seven real-time AI agents, and live federal verification APIs.</p><div class="srm-statuses"><span class="srm-status srm-status-live"><i aria-hidden="true"></i> 7-agent SRM · Live in production</span><span class="srm-status srm-status-staging"><i aria-hidden="true"></i> JEV evaluation · Staging QA only</span></div></div>${projectImage(p,"srm-hero-image")}</header><div class="srm-metrics" aria-label="Project outcomes"><article><span class="eyebrow">Production extraction</span><b>&gt;98%</b><p>W-9 and COI accuracy</p></article><article><span class="eyebrow">Supplier adoption</span><b>~350</b><p>Self-onboarded in six months</p></article><article><span class="eyebrow">Previous baseline</span><b>10–14 days</b><p>Supplier onboarding cycle</p></article><article><span class="eyebrow">Live orchestration</span><b>7 agents</b><p>Real-time production workflow</p></article></div><div class="case-layout srm-layout"><aside class="case-aside srm-aside"><span class="eyebrow">On this page</span><nav class="srm-toc" aria-label="Case study sections"><a href="#srm-problem">Problem &amp; evidence</a><a href="#srm-decisions">Product decisions</a><a href="#srm-system">Live AI system</a><a href="#srm-delivery">Delivery &amp; technology</a><a href="#srm-outcomes">Outcomes &amp; next steps</a></nav><a class="text-link" href="projects.html">All case studies →</a></aside><div class="case-content srm-content"><section id="srm-problem"><span class="eyebrow">01 / The opportunity</span><h2>Compliance work was stretching onboarding into weeks.</h2><p>US healthcare supply chain managers manually reviewed W-9 tax forms, Certificates of Insurance, business credentials, and federal exclusion registries. Fragmented email and PDF workflows slowed procurement for hospital buyers and created friction for suppliers.</p><div class="srm-evidence-grid"><article class="srm-evidence"><span class="srm-evidence-icon" aria-hidden="true">↘</span><div><span class="eyebrow">Operational signal</span><h3>10+ days in compliance review</h3><p>Workflow mapping exposed review cycles exceeding ten days within a 10–14 day onboarding baseline.</p></div></article><article class="srm-evidence"><span class="srm-evidence-icon" aria-hidden="true">◎</span><div><span class="eyebrow">Qualitative signal</span><h3>Compliance fatigue and rework</h3><p>Procurement manager interviews surfaced repeated manual-entry errors and frustration with disconnected checks.</p></div></article></div></section><section id="srm-decisions"><span class="eyebrow">02 / Scope &amp; decisions</span><h2>Automate the checks while keeping control of the risk.</h2><p>I owned the end-to-end PRD for the six-step supplier self-onboarding wizard, Buyer Golden Record workflow, and multi-agent architecture across Product, Engineering, and DevOps.</p><div class="srm-decision-grid"><article class="srm-decision srm-decision-selected"><span class="eyebrow">Chosen for production</span><h3>Constrained, real-time specialist agents</h3><p>Credential checks, banking guardrails, document extraction, and federal screening run synchronously as suppliers complete the workflow.</p></article><article class="srm-decision"><span class="eyebrow">Tradeoff evaluated</span><h3>Human-only review vs open-ended AI</h3><p>Manual review queues and unconstrained generative extraction were evaluated. The product uses automation for repeatable checks and routes conflicts into supplier remediation and buyer approval.</p></article></div><aside class="srm-staging-callout"><div class="srm-staging-mark">QA</div><div><span class="eyebrow">October 2026 · Isolated staging prototype</span><h3>JEV is not in production.</h3><p>A Structured JSON Evaluation and LLM-as-a-Judge layer was built to strengthen deterministic document handling. Promotion is paused while prompt calibration, schema adherence, hallucination resistance, and latency are validated in staging QA.</p></div></aside></section><section id="srm-system"><span class="eyebrow">03 / The product</span><h2>Seven agents coordinate the live supplier journey.</h2><p>The self-serve six-step portal replaces vendor intake spreadsheets and email threads. Specialists verify supplier identity and compliance in real time, then compile a tabbed Golden Record for buyer sign-off.</p><div class="srm-flow-intro"><span class="srm-flow-icon" aria-hidden="true">01</span><div><b>Supplier starts the six-step self-onboarding wizard</b><small>Eligibility, credentials, addresses, documents, and risk checks are orchestrated as the supplier progresses.</small></div></div><div class="srm-agent-flow"><div class="srm-agent-node">${srmAgents.slice(0,1).map(a=>`<article class="srm-agent"><div class="srm-agent-top"><span class="srm-agent-number">${a.n}</span><span class="srm-live-tag">Real-time · Live</span></div><h3>${a.name}</h3><p>${a.detail}</p></article>`).join("")}</div><div class="srm-flow-arrow" aria-hidden="true">↓</div><div class="srm-agent-parallel">${srmAgents.slice(1,3).map(a=>`<article class="srm-agent"><div class="srm-agent-top"><span class="srm-agent-number">${a.n}</span><span class="srm-live-tag">Real-time · Live</span></div><h3>${a.name}</h3><p>${a.detail}</p></article>`).join("")}</div><div class="srm-flow-arrow" aria-hidden="true">↓</div>${srmAgents.slice(3).map((a,i)=>`${i===2?`<aside class="srm-prototype-branch"><div><span class="eyebrow">Separate staging branch · October 2026</span><b>Agent 8 · Policy Judge &amp; JEV</b><p>Audits extracted JSON against strict schemas with LLM-as-a-Judge checks. Isolated QA prototype; it does not gate production records.</p></div><span class="srm-prototype-badge">NOT LIVE</span></aside>`:""}<article class="srm-agent"><div class="srm-agent-top"><span class="srm-agent-number">${a.n}</span><span class="srm-live-tag">Real-time · Live</span></div><h3>${a.name}</h3><p>${a.detail}</p></article>${i<srmAgents.slice(3).length-1?`<div class="srm-flow-arrow" aria-hidden="true">↓</div>`:""}`).join("")}</div><div class="srm-buyer-record"><div><span class="eyebrow">Destination</span><h3>Buyer approval queue</h3><p>Validated supplier data is assembled into a Golden Record with a clear audit trail.</p></div><div class="srm-record-tabs">${["Identity","Operations","Restricted Finance","Compliance","Audit Trail"].map(x=>`<span>${x}</span>`).join("")}</div></div></section><section id="srm-delivery"><span class="eyebrow">04 / End-to-end execution</span><h2>From workflow research through a measured launch.</h2><div class="srm-lifecycle">${srmLifecycle.map((step,i)=>`<article class="srm-lifecycle-step"><span class="srm-lifecycle-index">0${i+1}</span><div><h3>${step.name}</h3><p>${step.detail}</p></div></article>`).join("")}</div><div class="srm-stack-heading"><span class="eyebrow">Technology map</span><h3>Tools supporting the product system</h3></div><div class="srm-stack-grid">${srmStack.map(layer=>`<article class="srm-stack-card"><span class="eyebrow">${layer.group}</span><b>${layer.tools}</b><p>${layer.use}</p></article>`).join("")}</div></section><section id="srm-outcomes"><span class="eyebrow">05 / Impact &amp; learning</span><h2>A live product, with a separate path to stronger evaluation.</h2><div class="srm-time-result"><div class="srm-time-copy"><span class="eyebrow">End-to-end onboarding time</span><p>Includes automated multi-agent validation and Buyer Golden Record generation.</p></div><div class="srm-time-compare"><div><span>Pre-release baseline</span><b>10–14 days</b></div><span class="srm-time-arrow" aria-hidden="true">→</span><div class="srm-time-current"><span>Actionable outcome</span><b>80–90 minutes</b></div></div></div><div class="srm-results-grid"><article><span class="eyebrow">Supplier onboarding</span><h3>~350 suppliers</h3><p>Self-onboarded across the first six months after launch.</p></article><article><span class="eyebrow">Document extraction</span><h3>&gt;98% accuracy</h3><p>W-9 and COI extraction accuracy verified in production for digital PDFs.</p></article><article><span class="eyebrow">Product milestone</span><h3>First public B2B product</h3><p>Launched with real-time seven-agent verification and live API checks.</p></article></div><div class="srm-next-grid"><article><span class="eyebrow">Next · Document quality</span><h3>Investigate fallback OCR preprocessing</h3><p>Heavily degraded or handwritten scans can still fail extraction. Normalising low-resolution documents before LLM routing is the next path to investigate.</p></article><article><span class="eyebrow">Next · Evaluation readiness</span><h3>Keep JEV gated until it clears QA</h3><p>Finalise accuracy, schema-adherence, hallucination-resistance, and latency benchmarks before considering promotion from staging into production.</p></article></div></section></div></div>`;
