const masterDataProjectPage=function(p){
let html='<p class="back-link"><a href="projects.html">← All projects</a></p>';
html+='<header class="md-hero"><div class="md-hero-copy"><p class="eyebrow">SupplyCopia · Data infrastructure</p><h1>Global healthcare master data engine</h1><p class="md-role">Lead AI Product Manager — Data Infrastructure <span aria-hidden="true">·</span> September 2025 – Present</p><p class="md-deck">Unified fragmented vendor catalogues and public device records into one auditable product catalogue—so hospital teams can search consistently and see where duplicate purchasing hides.</p><div class="md-status"><span><i aria-hidden="true"></i> Live in production</span><span>Across US hospital client domains</span><span>Daily ETL · Real-time search</span></div></div>'+projectImage(p,'md-hero-image')+'</header>';
html+='<div class="md-metrics" aria-label="Master catalogue scope"><article><span class="eyebrow">Unified records</span><b>9M+</b><p>Healthcare product records</p></article><article><span class="eyebrow">Internal catalogue</span><b>2.8M</b><p>Enriched product records</p></article><article><span class="eyebrow">Public source</span><b>6.2M</b><p>GUDID device records</p></article><article><span class="eyebrow">Data refresh</span><b>Daily</b><p>Scheduled ETL and domain sync</p></article></div>';
html+='<div class="case-layout md-layout"><aside class="case-aside md-aside"><span class="eyebrow">On this page</span><nav class="md-toc" aria-label="Case study sections"><a href="#md-problem">Problem &amp; evidence</a><a href="#md-decisions">Architecture decisions</a><a href="#md-pipeline">Data pipeline</a><a href="#md-execution">Delivery &amp; technology</a><a href="#md-impact">Outcomes &amp; next steps</a></nav><a class="text-link" href="projects.html">All case studies →</a></aside><div class="case-content md-content">';
html+='<section id="md-problem"><span class="eyebrow">01 / The opportunity</span><h2>Duplicate products made shared procurement harder.</h2><p>Hospital networks were managing more than nine million records across internal catalogues and public GUDID registries. Without a shared taxonomy, the same supplier or medical SKU could appear under different names and descriptions, making it difficult for buyers to consolidate spend and negotiate volume discounts.</p><div class="md-evidence-grid"><article><span class="eyebrow">Database audits</span><h3>One company, multiple identities</h3><p>Schema and table audits found identical manufacturers recorded under aliases such as “Medtronic Inc.” and “Medtronic Ops.”</p></article><article><span class="eyebrow">Buyer support signals</span><h3>Overlapping contracts for the same SKU</h3><p>Support tickets described duplicate products listed with different names, descriptions, and formatting conventions.</p></article></div></section>';
html+='<section id="md-decisions"><span class="eyebrow">02 / Scope &amp; tradeoffs</span><h2>Resolve duplicates before they reach search.</h2><p>I owned the master data models, ETL pipeline specifications, and multi-domain synchronisation design with Data Engineering.</p><div class="md-options"><article><span class="md-option-number">01</span><h3>Exact string matching</h3><p>Too rigid to catch aliases, abbreviations, and inconsistent clinical descriptions.</p></article><article><span class="md-option-number">02</span><h3>AI on every search</h3><p>Query-time resolution across 9M+ records risked high latency and unpredictable inference cost.</p></article><article class="md-option-chosen"><span class="md-option-number">03 · Selected</span><h3>Batch ETL + semantic resolution</h3><p>Clean and cluster incoming data on a daily schedule, then serve search from precomputed, unified records.</p></article></div><aside class="md-tradeoff"><span class="eyebrow">The deliberate tradeoff</span><p>Daily batches can delay visibility of a newly added SKU. I accepted that small ingestion lag to keep compute costs predictable, maintain warehouse data hygiene, and protect fast query-time search.</p></aside></section>';
html+='<section id="md-pipeline"><span class="eyebrow">03 / The product</span><h2>One daily pipeline prepares records for real-time search.</h2><p>Public and internal feeds pass through six structured ETL stages. Resolution happens before warehouse load; procurement search queries prepared Golden Records instead of triggering expensive deduplication on every request.</p><div class="md-source-band"><div><span class="eyebrow">Public source</span><b>GUDID · 6.2M records</b></div><span class="md-source-plus" aria-hidden="true">+</span><div><span class="eyebrow">Internal source</span><b>Enriched catalogue · 2.8M records</b></div><span class="md-source-arrow" aria-hidden="true">→</span><div class="md-source-destination"><span class="eyebrow">Combined daily feed</span><b>9M+ product records</b></div></div><div class="md-pipeline">'+masterStages.map(function(stage,i){return '<article class="md-stage"><div class="md-stage-number">0'+(i+1)+'</div><div class="md-stage-copy"><span class="md-stage-kind">'+stage.kind+'</span><h3>'+stage.name+'</h3><p>'+stage.detail+'</p></div></article>'+(i<masterStages.length-1?'<div class="md-stage-arrow" aria-hidden="true">↓</div>':'')}).join('')+'</div><div class="md-serving"><div class="md-serving-icon" aria-hidden="true">⌕</div><div><span class="eyebrow">Serving layer · Real-time query</span><h3>Low-latency semantic search</h3><p>Warehouse-backed Golden Records and precomputed embeddings give procurement teams a unified search and cross-hospital spend view without running entity resolution at query time.</p></div><div class="md-serving-label">Live</div></div></section>';
html+='<section id="md-execution"><span class="eyebrow">04 / End-to-end execution</span><h2>Designed with the data lifecycle in view.</h2><div class="md-lifecycle">'+masterLifecycle.map(function(step,i){return '<article class="md-lifecycle-step"><span>0'+(i+1)+'</span><div><h3>'+step.name+'</h3><p>'+step.detail+'</p></div></article>'}).join('')+'</div><div class="md-stack-heading"><span class="eyebrow">Technology map</span><h3>Layers behind the master data engine</h3></div><div class="md-stack-grid">'+masterStack.map(function(layer){return '<article class="md-stack-card"><span class="eyebrow">'+layer.name+'</span><b>'+layer.tools+'</b><p>'+layer.detail+'</p></article>'}).join('')+'</div></section>';
html+='<section id="md-impact"><span class="eyebrow">05 / Outcomes &amp; learning</span><h2>A shared catalogue across hospital domains.</h2><div class="md-outcomes"><article class="md-outcome-feature"><span class="eyebrow">Unified master catalogue</span><b>9M+</b><p>2.8M internal enriched and 6.2M public GUDID records brought under a single Golden Record architecture on Redshift and Snowflake.</p></article><article><span class="eyebrow">Vendor &amp; SKU resolution</span><h3>Duplicates resolved before load</h3><p>Semantic and AI entity resolution collapse aliases and duplicate records ahead of warehouse publishing.</p></article><article><span class="eyebrow">Multi-client sync</span><h3>Daily domain updates</h3><p>Automated synchronisation keeps product catalogues aligned across US hospital domains.</p></article><article><span class="eyebrow">Procurement readiness</span><h3>A shared source of truth</h3><p>Consistent records help buyers see overlaps, consolidate spend, and prepare for contract negotiation.</p></article><article><span class="eyebrow">Compute &amp; search</span><h3>Predictable batch cost, fast queries</h3><p>Scheduled resolution controls compute while the serving layer returns low-latency search results.</p></article></div><aside class="md-next"><span class="eyebrow">Next iteration · Priority item streaming</span><h3>Reduce the wait for urgent and new SKUs.</h3><p>Daily ingestion introduces a small visibility lag. Event-driven vector streaming is a next-phase investigation for high-priority or newly introduced clinical products, while bulk catalogue refreshes remain on cost-efficient daily batches.</p></aside></section></div></div>';
return html;
};
