const ragProjectPage=function(p){
let html='<p class="back-link"><a href="projects.html">← All projects</a></p>';
html+='<header class="rag-hero"><div class="rag-hero-copy"><p class="eyebrow">SupplyCopia · Procurement analytics</p><h1>RAG-powered procurement analytics</h1><p class="rag-role">Individual Contributor AI Product Manager <span aria-hidden="true">·</span> September 2025 – Present</p><p class="rag-deck">Turned raw healthcare invoice lines into a grounded conversational analytics experience, so GPO stakeholders can investigate spend without waiting on a data-team queue.</p><div class="rag-status"><span><i aria-hidden="true"></i> Live in production</span><span>Three leading US GPOs</span><span>RAG + deterministic SQL</span></div></div>'+projectImage(p,'rag-hero-image')+'</header>';
html+='<div class="rag-metrics" aria-label="Procurement analytics outcomes"><article><span class="eyebrow">Actionable savings</span><b>~$1.5M</b><p>Across three leading US GPOs</p></article><article><span class="eyebrow">Production rollout</span><b>3 GPOs</b><p>Live in procurement workflows</p></article><article><span class="eyebrow">Architecture</span><b>6 stages</b><p>Gated query-to-answer flow</p></article><article><span class="eyebrow">Trust controls</span><b>2 measures</b><p>Context precision &amp; faithfulness</p></article></div>';
html+='<div class="case-layout rag-layout"><aside class="case-aside rag-aside"><span class="eyebrow">On this page</span><nav class="rag-toc" aria-label="Case study sections"><a href="#rag-problem">Problem &amp; evidence</a><a href="#rag-decisions">Architecture decisions</a><a href="#rag-system">Grounded query flow</a><a href="#rag-delivery">Delivery &amp; technology</a><a href="#rag-impact">Outcomes &amp; next steps</a></nav><a class="text-link" href="projects.html">All case studies →</a></aside><div class="case-content rag-content">';
html+='<section id="rag-problem"><span class="eyebrow">01 / The opportunity</span><h2>Spend questions were trapped behind a reporting queue.</h2><p>GPO stakeholders needed SQL expertise to query millions of raw healthcare invoice lines. Ad-hoc requests waited days for central data teams, while static BI dashboards demanded manual filtering and slicing. That friction made it harder to spot overlapping contracts, clinic-level price variance, and bulk-discount opportunities.</p><div class="rag-evidence-grid"><article><span class="eyebrow">Operational backlog</span><h3>Routine questions took days</h3><p>Procurement leaders queued requests for analysis such as total cardiac catheter spend across their top clinics.</p></article><article><span class="eyebrow">Workflow friction</span><h3>Static reports were hard to explore</h3><p>Commercial teams could not quickly reshape dashboard filters for new vendor negotiations and cross-facility comparisons.</p></article></div></section>';
html+='<section id="rag-decisions"><span class="eyebrow">02 / Scope &amp; decisions</span><h2>Let people ask in natural language; let SQL do the math.</h2><p>As the Individual Contributor PM, I owned both the raw-invoice data pipeline and the conversational dashboard interface.</p><div class="rag-options"><article><span class="rag-option-number">01</span><h3>Expand static BI dashboards</h3><p>Would leave stakeholders manually slicing reports for each ad-hoc negotiation question.</p></article><article><span class="rag-option-number">02</span><h3>Put an unconstrained LLM over raw data</h3><p>Could produce fluent but unsupported spend totals and create unacceptable financial trust risk.</p></article><article class="rag-option-chosen"><span class="rag-option-number">03 · Selected</span><h3>Hybrid semantic RAG + deterministic SQL</h3><p>Retrieve vetted schema and contract context, then run validated read-only aggregations in Snowflake.</p></article></div><aside class="rag-contract"><span class="rag-contract-mark" aria-hidden="true">=</span><div><span class="eyebrow">The grounding contract</span><h3>Snowflake computes every number.</h3><p>The model only synthesises retrieved context and database-verified rows, and cites the underlying query slice. No LLM arithmetic or unsupported totals.</p></div></aside></section>';
html+='<section id="rag-system"><span class="eyebrow">03 / The product</span><h2>Six gates turn a question into a verifiable answer.</h2><p>The conversational dashboard is embedded in the procurement workflow. A tenant-scoped query moves through retrieval, reranking, safe SQL, grounded synthesis, and continuous evaluation.</p><div class="rag-query"><span class="eyebrow">Example stakeholder question</span><b>“What is our total spend on cardiac catheters across our top three clinics?”</b></div><div class="rag-flow">'+ragStages.map(function(stage,i){return '<article class="rag-stage"><div class="rag-stage-number">0'+(i+1)+'</div><div><span class="rag-stage-label">'+(i<2?'RETRIEVE':i===2?'RERANK':i===3?'EXECUTE':i===4?'RESPOND':'EVALUATE')+'</span><h3>'+stage.name+'</h3><p>'+stage.detail+'</p></div></article>'+(i<ragStages.length-1?'<div class="rag-stage-arrow" aria-hidden="true">↓</div>':'')}).join('')+'</div><div class="rag-response"><div><span class="eyebrow">Stakeholder sees</span><h3>A concise answer with its evidence</h3><p>Verified totals, an interactive chart, a downloadable audit table, and a citation to the exact query slice.</p></div><div class="rag-response-pills"><span>Verified SQL</span><span>Grounded summary</span><span>Interactive chart</span></div></div></section>';
html+='<section id="rag-delivery"><span class="eyebrow">04 / End-to-end execution</span><h2>Built from request patterns through audited release.</h2><div class="rag-lifecycle">'+ragLifecycle.map(function(step,i){return '<article class="rag-lifecycle-step"><span>0'+(i+1)+'</span><div><h3>'+step.name+'</h3><p>'+step.detail+'</p></div></article>'}).join('')+'</div><div class="rag-stack-heading"><span class="eyebrow">Technology map</span><h3>Layers behind the analytics experience</h3></div><div class="rag-stack-grid">'+ragStack.map(function(layer){return '<article class="rag-stack-card"><span class="eyebrow">'+layer.name+'</span><b>'+layer.tools+'</b><p>'+layer.detail+'</p></article>'}).join('')+'</div></section>';
html+='<section id="rag-impact"><span class="eyebrow">05 / Outcomes &amp; learning</span><h2>From reporting backlog to self-serve analysis.</h2><div class="rag-outcomes"><article class="rag-outcome-feature"><span class="eyebrow">Verified cost savings</span><b>~$1.5M</b><p>Actionable savings identified and driven across three leading US GPOs.</p></article><article><span class="eyebrow">Reporting turnaround</span><h3>Multi-day queue → self-serve answers</h3><p>Stakeholders can query spend in natural language inside procurement workflows without waiting for data-team intervention.</p></article><article><span class="eyebrow">Financial trust</span><h3>Grounded results, not model math</h3><p>Deterministic Snowflake SQL computes totals; context precision and faithfulness checks govern retrieved evidence.</p></article><article><span class="eyebrow">End-to-end ownership</span><h3>Pipeline through dashboard</h3><p>Invoice enrichment and conversational analytics were built and deployed as one connected product experience.</p></article></div><aside class="rag-next"><span class="eyebrow">Next iteration · Predictive questions</span><h3>Move from “what happened?” to “what if?”</h3><p>Stakeholders are asking how volume shifts could affect bulk-tier pricing next quarter. A predictive ML forecasting layer on the enriched Snowflake pipeline is the next capability to investigate alongside historical RAG analysis.</p></aside></section></div></div>';
return html;
};
